export const SCHEMA = 1;
export const id = () => crypto.randomUUID();
export function today() { return new Intl.DateTimeFormat('sv-SE', {timeZone:'Asia/Seoul'}).format(new Date()); }
export function shift(date, n=1) { const d=new Date(date+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return d.toISOString().slice(0,10); }
export function emptyState() { return {schema:SCHEMA,categories:[{id:'school',name:'학교'},{id:'muniv',name:'MUNIV'},{id:'personal',name:'개인'},{id:'career',name:'취업'}],tasks:[],days:{},manualOrder:false}; }
export function day(s,date) { return s.days[date] ||= {plan:[],actual:[],tasks:{},journal:[]}; }
export function categoryName(s, cid) { return s.categories.find(c=>c.id===cid)?.name || 'Inbox'; }
export function snapshot(s,t) { return {...structuredClone(t),categoryName:t.categoryName||categoryName(s,t.category)}; }
export function logTask(s,t) { if(t.date) day(s,t.date).tasks[t.id]=snapshot(s,t); }
export function addTask(s,title,props={}) { if(!title.trim()) throw Error('할 일 제목을 입력해주세요.'); const task={id:id(),title:title.trim(),category:null,date:null,status:'pending',parentId:null,appointment:false,collapsed:false,note:'',createdAt:Date.now(),order:s.tasks.reduce((m,t)=>Math.max(m,t.order),-1)+1,...props};s.tasks.push(task);logTask(s,task);return task; }
export function descendants(s, tid) { const result=[]; const visit=x=>{ for(const t of s.tasks.filter(t=>t.parentId===x)){result.push(t);visit(t.id);} };visit(tid);return result; }
export function editTask(s,tid,props) { const t=s.tasks.find(t=>t.id===tid);if(!t)throw Error('할 일을 찾을 수 없습니다.');if(props.title!==undefined&&!props.title.trim())throw Error('할 일 제목을 입력해주세요.');const oldDate=t.date,oldCategory=t.category;Object.assign(t,props);logTask(s,t);if(oldDate!==t.date||oldCategory!==t.category){for(const child of descendants(s,t.id)){child.date=t.date;child.category=t.category;logTask(s,child);}}return t; }
export function changeStatus(s,tid,date,status) { const t=s.tasks.find(t=>t.id===tid), record=day(s,date).tasks[tid]; if(!t&&!record)throw Error('할 일을 찾을 수 없습니다.'); const src=t&&t.date===date?t:record; src.status=status;day(s,date).tasks[tid]=snapshot(s,src);
  if(status==='partial') { let continuation=s.tasks.find(t=>t.continuationOf===tid&&t.sourceDate===date);if(!continuation){continuation=addTask(s,src.title,{category:src.category,date:shift(date),continuationOf:tid,sourceDate:date,appointment:src.appointment,note:src.note||''}); if(t)for(const c of descendants(s,tid).filter(c=>c.status!=='done'))addTask(s,c.title,{category:c.category,date:shift(date),parentId:continuation.id});}return continuation; }
  if(status==='done'){const generated=s.tasks.filter(t=>t.continuationOf===tid&&t.sourceDate===date);for(const c of generated){const removed=new Set([c.id,...descendants(s,c.id).map(x=>x.id)]);s.tasks=s.tasks.filter(x=>!removed.has(x.id));for(const d of Object.values(s.days))for(const rid of removed)delete d.tasks[rid];}}
}
export function moveTask(s,tid,date) { const t=s.tasks.find(t=>t.id===tid);if(!t)return; const from=t.date;if(from&&day(s,from).tasks[tid])day(s,from).tasks[tid].movedTo=date;editTask(s,tid,{date,status:'pending'}); }
export function postpone(s,date,includeAppointments=false) { const list=s.tasks.filter(t=>!t.parentId&&t.date===date&&t.status!=='done'&&(includeAppointments||!t.appointment));let count=0;for(const t of list){if(t.status==='partial'){changeStatus(s,t.id,date,'partial');day(s,date).tasks[t.id].movedTo=shift(date);}else moveTask(s,t.id,shift(date));count++;}return count; }
export function removeTask(s,tid) { const ids=new Set([tid,...descendants(s,tid).map(t=>t.id)]);s.tasks=s.tasks.filter(t=>!ids.has(t.id));for(const d of Object.values(s.days))for(const rid of ids)delete d.tasks[rid]; }
export function ordered(s,ts=s.tasks) { return [...ts].sort(s.manualOrder?(a,b)=>a.order-b.order:(a,b)=>a.createdAt-b.createdAt||a.order-b.order); }
export function reorder(s,source,target) { const a=s.tasks.find(t=>t.id===source),b=s.tasks.find(t=>t.id===target);if(!a||!b||a.parentId!==b.parentId)return;const order=ordered(s);const from=order.indexOf(a);order.splice(from,1);order.splice(order.indexOf(b),0,a);order.forEach((t,i)=>t.order=i);s.manualOrder=true; }
export function indent(s,tid,out=false) { const t=s.tasks.find(t=>t.id===tid);if(!t)return; if(out){const parent=s.tasks.find(p=>p.id===t.parentId);t.parentId=parent?.parentId||null;}else{const siblings=ordered(s).filter(x=>x.parentId===t.parentId);const previous=siblings[siblings.indexOf(t)-1];if(!previous)return;t.parentId=previous.id;t.date=previous.date;t.category=previous.category;previous.collapsed=false;}logTask(s,t); }
export function addBlock(s,date,mode,props) { if(!['plan','actual'].includes(mode))throw Error('기록 종류를 확인해주세요.');const t=s.tasks.find(t=>t.id===props.taskId);const block={id:id(),title:t?.title||'',categoryName:t?categoryName(s,t.category):'일상',taskId:t?.id||null,status:t?.status||'pending',appointment:t?.appointment||false,start:600,end:660,allDay:false,...props};if(!block.title.trim())throw Error('기록 제목을 입력해주세요.');if(!block.allDay&&(!Number.isFinite(block.start)||!Number.isFinite(block.end)||block.start<0||block.end>1440||block.end<=block.start))throw Error('종료 시간은 시작 시간보다 뒤여야 합니다.');day(s,date)[mode].push(block);if(t&&(mode==='plan'||!t.date)&&t.date!==date)moveTask(s,t.id,date);return block; }
export function updateBlock(s,date,mode,bid,props) { const b=day(s,date)[mode].find(b=>b.id===bid);if(!b)return;const next={...b,...props};if(!next.title.trim())throw Error('기록 제목을 입력해주세요.');if(!next.allDay&&(!Number.isFinite(next.start)||!Number.isFinite(next.end)||next.end<=next.start||next.start<0||next.end>1440))throw Error('시간 범위를 확인해주세요.');Object.assign(b,props); }
export function actualFromPlan(s,date,bid,start,end) { const b=day(s,date).plan.find(x=>x.id===bid);if(!b)throw Error('계획을 선택해주세요.');return addBlock(s,date,'actual',{...structuredClone(b),id:id(),start,end}); }
export function counts(s,date) { const tasks=Object.values(s.days[date]?.tasks||{}).filter(t=>!t.parentId);return {done:tasks.filter(t=>t.status==='done').length,partial:tasks.filter(t=>t.status==='partial').length,pending:tasks.filter(t=>t.status==='pending').length}; }
export function duration(s,date,mode) { return (s.days[date]?.[mode]||[]).filter(b=>!b.allDay).reduce((n,b)=>n+b.end-b.start,0); }
export function embed(s,date,kind,source) { return {id:id(),type:'card',kind,date,title:source.title,categoryName:source.categoryName||categoryName(s,source.category),status:source.status||'pending',start:source.start??null,end:source.end??null,allDay:source.allDay||false}; }
const validDate=x=>{if(typeof x!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(x))return false;const d=new Date(x+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===x;};
const validId=x=>typeof x==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(x);
export function validateState(s) {
  if(!s||s.schema!==SCHEMA||!Array.isArray(s.tasks)||!Array.isArray(s.categories)||!s.days||typeof s.days!=='object'||Array.isArray(s.days))throw Error('이 앱의 백업 파일이 아닙니다.');
  const seen=new Set();for(const t of s.tasks){if(!validId(t.id)||seen.has(t.id)||typeof t.title!=='string'||!['pending','partial','done'].includes(t.status)||!Number.isFinite(t.order)||!Number.isFinite(t.createdAt)||(t.date&&!validDate(t.date))||(t.sourceDate&&!validDate(t.sourceDate))||(t.category&&!validId(t.category)))throw Error('할 일 데이터가 올바르지 않습니다.');seen.add(t.id);}
  const categoryIds=new Set();for(const c of s.categories){if(!validId(c.id)||categoryIds.has(c.id)||typeof c.name!=='string')throw Error('카테고리 데이터가 올바르지 않습니다.');categoryIds.add(c.id);}
  for(const t of s.tasks){if(t.parentId&&!seen.has(t.parentId))throw Error('하위 작업의 상위 항목이 없습니다.');let current=t;const chain=new Set();while(current){if(chain.has(current.id))throw Error('하위 작업 연결이 올바르지 않습니다.');chain.add(current.id);current=s.tasks.find(x=>x.id===current.parentId);}}
  for(const [date,d] of Object.entries(s.days)){if(!validDate(date)||!Array.isArray(d.plan)||!Array.isArray(d.actual)||!Array.isArray(d.journal)||!d.tasks||typeof d.tasks!=='object'||Array.isArray(d.tasks))throw Error('일별 기록이 올바르지 않습니다.');for(const t of Object.values(d.tasks)){if(!validId(t.id)||typeof t.title!=='string'||!['pending','partial','done'].includes(t.status)||(t.date&&!validDate(t.date))||(t.sourceDate&&!validDate(t.sourceDate))||(t.movedTo&&!validDate(t.movedTo))||(t.parentId&&!validId(t.parentId)))throw Error('일별 할 일이 올바르지 않습니다.');}for(const b of [...d.plan,...d.actual]){if(!validId(b.id)||typeof b.title!=='string'||!Number.isFinite(b.start)||!Number.isFinite(b.end)||b.start<0||b.end>1440||(!b.allDay&&b.end<=b.start))throw Error('시간표 기록이 올바르지 않습니다.');}for(const b of d.journal){if(!['text','card','photo'].includes(b.type)||!validId(b.id))throw Error('일기 기록이 올바르지 않습니다.');if(b.type==='text'&&typeof b.text!=='string')throw Error('일기 본문이 올바르지 않습니다.');if(b.type==='photo'&&!/^data:image\/(jpeg|png|webp);base64,/.test(b.src||''))throw Error('사진 데이터가 올바르지 않습니다.');if(b.type==='card'&&(typeof b.title!=='string'||!['TODO','PLAN','ACTUAL'].includes(b.kind)||!validDate(b.date)))throw Error('기록 카드가 올바르지 않습니다.');}}
  return s;
}
